def test_loose_version_cmp_detects_lower_version():
    assert LooseVersion("1.0")._cmp(LooseVersion("2.0")) == -1


def test_loose_version_cmp_detects_higher_version():
    assert LooseVersion("2.0")._cmp(LooseVersion("1.0")) == 1
